package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import java.util.*;
/** One canonical owner/state/durability record. Only the door's transition needs ticking. */
public final class Ps01BlockEntity extends BlockEntity{
 public UUID owner;public double structure=Ps01Config.HEALTH.get(),doorHealth=Ps01Config.DOOR_HEALTH.get();public boolean lights;private float from,target;private long transition;private int step;private UUID actor;private long dustAt=-20;private boolean removing;
 public Ps01BlockEntity(BlockPos p,BlockState s){super(AddonBlockEntities.PS01.get(),p,s);}
 public Direction facing(){return getBlockState().getValue(Ps01Block.FACING);}
 public int doorStep(){return doorHealth<=0?19:step;}
 public float progress(float partial){if(doorHealth<=0)return 1;float duration=Math.max(1,Math.abs(target-from)*Ps01Geometry.DOOR_TICKS);return from+(target-from)*net.minecraft.util.Mth.clamp((level.getGameTime()-transition+partial)/duration,0,1);}
 public double integrity(){return Math.max(0,Math.min(1,structure/Ps01Config.HEALTH.get()));}public double doorIntegrity(){return Math.max(0,Math.min(1,doorHealth/Ps01Config.DOOR_HEALTH.get()));}
 public boolean permitted(Player p){return owner==null||owner.equals(p.getUUID())||p.hasPermissions(2);}
 public void toggle(Player p){if(doorHealth<=0){p.displayClientMessage(net.minecraft.network.chat.Component.literal("The steel door is destroyed"),true);return;}from=progress(0);target=target>.5f?0:1;transition=level.getGameTime();actor=p.getUUID();level.playSound(null,worldPosition,target>0?net.minecraft.sounds.SoundEvents.IRON_DOOR_OPEN:net.minecraft.sounds.SoundEvents.IRON_DOOR_CLOSE,net.minecraft.sounds.SoundSource.BLOCKS,.75f,1);changed();}
 public void toggleLights(){lights=!lights;for(int i=0;i<Ps01Geometry.BODY.length;i++)if(Ps01Geometry.lamp(Ps01Geometry.BODY[i])){var p=Ps01Geometry.cell(worldPosition,facing(),Ps01Geometry.BODY[i]);var s=level.getBlockState(p);if(s.getBlock()instanceof Ps01Block)level.setBlock(p,s.setValue(Ps01Block.LIT,lights),3);}level.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.LEVER_CLICK,net.minecraft.sounds.SoundSource.BLOCKS,.4f,lights?.65f:.5f);changed();}
 public static void tick(Level world,BlockPos pos,BlockState state,Ps01BlockEntity b){if(world.isClientSide||b.removing||b.doorHealth<=0||b.from==b.target)return;float at=b.progress(0);int next=Math.round(Ps01Geometry.angle(at)/5);if(next==b.step){if(at==b.target){b.from=b.target;b.changed();world.playSound(null,pos,net.minecraft.sounds.SoundEvents.IRON_TRAPDOOR_CLOSE,net.minecraft.sounds.SoundSource.BLOCKS,.3f,.8f);}return;}var sweep=new ArrayList<AABB>();sweep.addAll(Ps01Geometry.leaf(b.step));sweep.addAll(Ps01Geometry.leaf(next));boolean blocked=false;var bounds=Ps01Geometry.box(pos,b.facing(),new AABB(-1.5,.25,-4.35,.2,2.8,-2.75));for(var e:world.getEntities((Entity)null,bounds,e->!e.isSpectator()&&!e.isRemoved()&&!(e instanceof Ps01Seat))){for(var box:sweep)if(Ps01Geometry.box(pos,b.facing(),box).intersects(e.getBoundingBox().deflate(.012))){blocked=true;break;}if(blocked)break;}
  if(blocked){b.from=b.step/18f;b.target=b.from;b.transition=world.getGameTime();if(b.actor!=null&&world instanceof ServerLevel l){var p=l.getServer().getPlayerList().getPlayer(b.actor);if(p!=null)p.displayClientMessage(net.minecraft.network.chat.Component.literal("Door blocked — clear the doorway and try again"),true);}b.changed();return;}
  b.step=next;b.updateDoor();if(at==b.target){b.from=b.target;world.playSound(null,pos,net.minecraft.sounds.SoundEvents.IRON_TRAPDOOR_CLOSE,net.minecraft.sounds.SoundSource.BLOCKS,.3f,.8f);b.changed();}
 }
 private void updateDoor(){for(int i=0;i<Ps01Geometry.DOOR.length;i++){var p=Ps01Geometry.cell(worldPosition,facing(),Ps01Geometry.DOOR[i]);var s=level.getBlockState(p);if(s.getBlock()instanceof Ps01Block block&&block.door&&s.getValue(Ps01Block.STEP)!=doorStep())level.setBlock(p,s.setValue(Ps01Block.STEP,doorStep()),3);}}
 public void hit(double amount,boolean leaf,Vec3 location){if(!(level instanceof ServerLevel l)||removing||!(amount>0))return;if(leaf){if(doorHealth<=0)return;doorHealth=Math.max(0,doorHealth-amount);if(doorHealth==0){from=target=1;step=19;updateDoor();}}else structure=Math.max(0,structure-amount);dust(location,structure<=0?10:3,leaf);changed();if(structure<=0)remove(null,false,true);}
 private void dust(Vec3 at,int count,boolean leaf){if(!(level instanceof ServerLevel l)||l.getGameTime()-dustAt<4)return;dustAt=l.getGameTime();for(int i=0;i<count;i++)RubbleEvents.burst(l,BlockPos.containing(at.add((i%3-1)*.45,(i/3)*.15,0)),(leaf?Blocks.IRON_BLOCK:Blocks.GRAY_CONCRETE).defaultBlockState(),0);}
 public boolean remove(Player player,boolean drop,boolean destroyed){if(!(level instanceof ServerLevel l)||removing||player!=null&&!permitted(player))return false;if(player!=null){for(var cell:Ps01WorldData.all(facing(),worldPosition)){if(!l.hasChunkAt(cell)||!l.mayInteract(player,cell))return false;var event=new net.minecraftforge.event.level.BlockEvent.BreakEvent(l,cell,l.getBlockState(cell),player);if(net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event))return false;}}var seats=l.getEntitiesOfClass(Ps01Seat.class,getRenderBoundingBox().inflate(1),s->s.root().equals(worldPosition));if(!destroyed)for(var seat:seats)for(var p:seat.getPassengers())if(!(p instanceof LivingEntity living)||seat.safe(living)==null){if(player!=null)player.displayClientMessage(net.minecraft.network.chat.Component.literal("Clear a safe standing space before removing the shelter"),true);return false;}
  removing=true;var item=new ItemStack(AddonItems.PS01.get());var n=Ps01Item.data(item);var packed=state();packed.putFloat("From",doorStep()==19?1:step/18f);packed.putFloat("Target",doorStep()==19?1:step/18f);packed.putLong("Transition",0);n.put("ShelterState",packed);Ps01Item.data(item,n);for(var seat:seats)seat.ejectSafely();Direction f=facing();Ps01WorldData.get(l).removed(l,worldPosition,f);if(drop&&player!=null&&!player.isCreative())net.minecraftforge.items.ItemHandlerHelper.giveItemToPlayer(player,item);
  if(destroyed&&RubbleConfig.ENABLED.get()&&RubbleConfig.MODE.get()!=RubbleConfig.Mode.VISUAL){var data=RubbleTasks.get(l);for(int i=0;i<4;i++){var p=BlockPos.containing(Ps01Geometry.point(worldPosition,f,i%2==0?-2.5:2.5,0,i<2?-1.5:1.5));if(l.hasChunkAt(p)&&l.getBlockState(p).isAir())data.deposits.add(new RubbleTasks.Deposit(UUID.randomUUID(),p,Blocks.GRAY_CONCRETE.defaultBlockState(),owner));}data.setDirty();}return true;
 }
 public CompoundTag state(){var n=new CompoundTag();if(owner!=null)n.putUUID("Owner",owner);n.putDouble("Structure",structure);n.putDouble("DoorHealth",doorHealth);n.putBoolean("Lights",lights);n.putFloat("From",from);n.putFloat("Target",target);n.putLong("Transition",transition);n.putInt("Step",step);return n;}
 public void restore(CompoundTag n){owner=n.hasUUID("Owner")?n.getUUID("Owner"):null;structure=n.contains("Structure")?Math.max(0,Math.min(Ps01Config.HEALTH.get(),n.getDouble("Structure"))):Ps01Config.HEALTH.get();doorHealth=n.contains("DoorHealth")?Math.max(0,Math.min(Ps01Config.DOOR_HEALTH.get(),n.getDouble("DoorHealth"))):Ps01Config.DOOR_HEALTH.get();lights=n.getBoolean("Lights");from=net.minecraft.util.Mth.clamp(n.getFloat("From"),0,1);target=net.minecraft.util.Mth.clamp(n.getFloat("Target"),0,1);transition=n.getLong("Transition");step=net.minecraft.util.Mth.clamp(n.getInt("Step"),0,19);}
 public void changed(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
 public void refreshParts(){if(!(level instanceof ServerLevel))return;updateDoor();for(int i=0;i<Ps01Geometry.BODY.length;i++)if(Ps01Geometry.lamp(Ps01Geometry.BODY[i])){var p=Ps01Geometry.cell(worldPosition,facing(),Ps01Geometry.BODY[i]);var s=level.getBlockState(p);if(s.getBlock()instanceof Ps01Block)level.setBlock(p,s.setValue(Ps01Block.LIT,lights),3);}}
 @Override public void onLoad(){super.onLoad();if(level instanceof ServerLevel l){Ps01WorldData.get(l).add(worldPosition,facing());if(doorHealth>0&&from!=target){from=step/18f;transition=l.getGameTime();changed();}l.getServer().tell(new net.minecraft.server.TickTask(l.getServer().getTickCount()+1,()->{if(!isRemoved())refreshParts();}));}}
 @Override protected void saveAdditional(CompoundTag n){super.saveAdditional(n);n.merge(state());}@Override public void load(CompoundTag n){super.load(n);restore(n);}
 @Override public CompoundTag getUpdateTag(){return saveWithoutMetadata();}@Override public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}
 public AABB getRenderBoundingBox(){return Ps01Geometry.bounds(worldPosition,facing());}
}
